INSERT INTO bank_faults(action_id,user_id,submit_mode,lookup_mode)
SELECT #{actionId},#{userId},#{submitMode},#{lookupMode}
FROM actions WHERE id=#{actionId} AND user_id=#{userId}
  AND NOT EXISTS(SELECT 1 FROM bank_faults WHERE action_id=#{actionId} AND NOT(user_id <=> #{userId}))
ON DUPLICATE KEY UPDATE submit_mode=#{submitMode},lookup_mode=#{lookupMode}
